css:
body {
  font-family: Georgia, serif;
  background: #f5f2ee;
  color: #1a1a1a;
  padding: 3rem 1.5rem;
  min-height: 90vh;
}

h2 {
  font-size: 1.25rem;
  font-weight: normal;
  letter-spacing: 0.04em;
  margin-bottom: 1rem;
  color: #555;
}

/* ─── The only trick you need ─── */
.table-wrap {
  overflow: auto; /* scrolls both axes when needed  */
  max-height: 360px; /* triggers vertical scroll        */
  border: 1px solid #d6d0c8;
  border-radius: 6px;
}

table {
  width: 100%;
  min-width: 640px; /* prevents collapse on small screens */
  border-collapse: collapse;
}

/* Sticky header */
thead th {
  position: sticky;
  top: 0;
  background: #eae6df;
  z-index: 1;
}

th,
td {
  text-align: left;
  padding: 0.75rem 1.25rem;
  font-size: 0.9rem;
  white-space: nowrap;
  border-bottom: 1px solid #ddd8d0;
}

th {
  font-weight: normal;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.7rem;
  color: #888;
}

tbody tr:last-child td {
  border-bottom: none;
}

tbody tr:hover td {
  background: #ede9e2;
}

td:first-child,
th:first-child {
  position: sticky;
  left: 0;
  background: #eae6df; /* match your row background */
  z-index: 1;
}

thead th:first-child {
  z-index: 2; /* sits above both sticky directions */
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary-color: #111827;
  --secondary-color: #374151;
  --accent-color: #2563eb;
  --text-primary: #111827;
  --text-secondary: #6b7280;
  --background: #ffffff;
  --background-alt: #f9fafb;
  --border-color: #e5e7eb;
  --nav-height: 72px;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  background: var(--background-alt);
  color: var(--text-primary);
  line-height: 1.6;
}

.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--background);
  border-bottom: 1px solid var(--border-color);
  z-index: 1000;
  transition: all 0.3s ease;
}

.navbar.scrolled {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.nav-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 clamp(16px, 4vw, 32px);
  height: var(--nav-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--text-primary);
  font-weight: 700;
  font-size: 20px;
  z-index: 1001;
}

.logo-icon {
  width: 32px;
  height: 32px;
  stroke-width: 2;
}

.logo-text {
  letter-spacing: -0.5px;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 28px;
  height: 20px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  z-index: 1001;
  transition: all 0.3s ease;
}

.hamburger-line {
  width: 100%;
  height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: all 0.3s ease;
}

.hamburger.active .hamburger-line:nth-child(1) {
  transform: translateY(9px) rotate(45deg);
}

.hamburger.active .hamburger-line:nth-child(2) {
  opacity: 0;
}

.hamburger.active .hamburger-line:nth-child(3) {
  transform: translateY(-9px) rotate(-45deg);
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: clamp(24px, 4vw, 48px);
}

.nav-list {
  display: flex;
  align-items: center;
  gap: clamp(16px, 3vw, 32px);
  list-style: none;
}

.nav-link {
  text-decoration: none;
  color: var(--text-secondary);
  font-size: 15px;
  font-weight: 500;
  transition: color 0.2s ease;
  position: relative;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent-color);
  transition: width 0.3s ease;
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-btn {
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  white-space: nowrap;
  display: inline-block;
}

.nav-btn.secondary {
  color: var(--text-primary);
  background: transparent;
  border: 1px solid var(--border-color);
}

.nav-btn.secondary:hover {
  background: var(--background-alt);
}

.nav-btn.primary {
  color: #ffffff;
  background: var(--accent-color);
  border: 1px solid var(--accent-color);
}

.nav-btn.primary:hover {
  background: #1d4ed8;
  border-color: #1d4ed8;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.25);
}

.main-content {
  margin-top: var(--nav-height);
}

.hero-section {
  padding: clamp(60px, 12vw, 120px) clamp(16px, 4vw, 32px);
  text-align: center;
  background: var(--background);
}

.hero-container {
  max-width: 800px;
  margin: 0 auto;
}

.hero-title {
  font-size: clamp(32px, 6vw, 56px);
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 20px;
  letter-spacing: -1px;
  line-height: 1.1;
}

.hero-description {
  font-size: clamp(16px, 3vw, 20px);
  color: var(--text-secondary);
  margin-bottom: 40px;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-btn {
  padding: 14px 32px;
  border-radius: 10px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.hero-btn.primary {
  background: var(--accent-color);
  color: #ffffff;
}

.hero-btn.primary:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.3);
}

.hero-btn.secondary {
  background: var(--background-alt);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.hero-btn.secondary:hover {
  background: #f3f4f6;
}

.content-section {
  padding: clamp(40px, 8vw, 80px) clamp(16px, 4vw, 32px);
}

.content-container {
  max-width: 1200px;
  margin: 0 auto;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: clamp(24px, 4vw, 32px);
}

.feature-card {
  background: var(--background);
  padding: clamp(24px, 4vw, 32px);
  border-radius: 12px;
  border: 1px solid var(--border-color);
  transition: all 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.08);
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: var(--background-alt);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.feature-icon svg {
  width: 28px;
  height: 28px;
  stroke: var(--accent-color);
  stroke-width: 2;
}

.feature-title {
  font-size: clamp(18px, 3vw, 22px);
  font-weight: 700;
  color: var(--text-primary);
