import { naturalStickyTop } from "https://esm.sh/natural-sticky";

const header = document.getElementById("header");

// Initialize the header script
naturalStickyTop(header);

// Listen for state changes
header.addEventListener("natural-sticky", (event) => {
  const state = event.detail.state;
  console.log("State changed to:", state);

  // Update text content based on state
  if (state === "home") {
    header.textContent = "Header at Top";
  } else {
    header.textContent = "Header Scrolled";
  }

  // Update class for styling
  header.classList.remove("home", "sticky", "relative");
  header.classList.add(state);
});

// Set initial state on load
header.classList.add("home");

