import { naturalStickyTop } from "https://esm.sh/natural-sticky";

// Main header - reserves space (standard behavior)
naturalStickyTop(document.getElementById("header"));

// Floating button - no space reserved
const buttonContainer = document.getElementById("buttonContainer");
const floatingButton = document.getElementById("floatingButton");
naturalStickyTop(buttonContainer, {
  reserveSpace: false
});

// Listen for state changes on the floating button's container
buttonContainer.addEventListener("natural-sticky", (event) => {
  const state = event.detail.state;
  console.log("Floating button state changed to:", state);

  // Update text content
  floatingButton.textContent = `State: ${state}`;

  // Update class for styling
  floatingButton.classList.remove("home", "sticky", "relative");
  floatingButton.classList.add(state);
});

// Set initial state on load
floatingButton.classList.add("home");

