// Diese Funktion fügt ein Event-Listener hinzu, der auf das Scrollen des Fensters reagiert.
window.addEventListener('scroll', function() {
    // Selektiert das HTML-Element mit der Klasse 'header' und speichert es in der Variable 'header'.
    var header = document.querySelector('.header');
    // Fügt der Klasse 'header' die Klasse 'small' hinzu, wenn die vertikale Scrollposition größer als 0 ist, 
    // andernfalls entfernt es die Klasse 'small'.
    header.classList.toggle('small', window.scrollY > 0);
});

