@import url("https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900;1,100;1,300;1,400;1,500;1,700;1,900&display=swap");

* {
	margin: 0;
	padding: 0;
	box-sizing: border-box;
}
html {
	font-size: 10px;
	scroll-behavior: smooth;
}
body {
	font-family: "Roboto", sans-serif;
	font-size: 1.6rem;
	line-height: 1.5;
	font-weight: 300;
	letter-spacing: -0.5px;
	background: #fff;
	color: $dark-1;
}
h1,
h2,
h3,
h4 {
	color: $default;
	margin-bottom: 1rem;
	font-weight: 600;
}
p {
	margin-bottom: 1rem;
}
header {
	padding: 15px;
	background: $default;
	color: $light-1;
	text-align: center;
	span,
	.logo > * {
		color: $highlight;
	}
	&.navigation {
		display: flex;
		justify-content: space-between;
		align-items: center;
		position: -webkit-sticky;
		position: sticky;
		top: 0;
		z-index: 999;
		a {
			color: $light-2;
			text-decoration: none;
			margin: 0 5px;
			&.logo {
				margin: 0;
				padding: 0;
				font-size: 1.5em;
				line-height: 1;
				margin-right: 10px;
			}
		}
	}
}

main {
	display: grid;
	grid-template-columns: 1.3fr 4fr 1fr;
	grid-gap: 30px;
	aside,
	section {
		padding-top: 50px;
		padding-bottom: 50px;
	}
	section {
		padding-left: 20px;
		padding-right: 20px;
		h2 {
			color: $dark;
		}
	}
	aside {
		padding-left: 20px;
		padding-right: 20px;
		> ol,
		> ul {
			position: -webkit-sticky;
			position: sticky;
			top: 80px;
			a {
				text-decoration: none;
				display: inline-block;
				&:hover {
					color: $dark-1;
				}
			}
		}
		ul,
		ol {
			list-style: none;
		}
		ul li > ul {
			padding-left: 10px;
		}
		&.sidebar-left {
			background: $light;
			border-right: 1px solid $light-1;
			font-size: 1.8rem;
			a {
				color: $dark;
			}
			ol > li > a {
				font-size: 2rem;
				font-weight: 400;
				margin: 10px 0;
			}
		}
		&.sidebar-right {
			color: $dark-1;
			ul:first-child {
				border-left: 1px solid $light-1;
				padding-left: 15px;
			}
			a {
				color: $dark-1;
			}
		}
	}
}

footer {
	background: $default;
	color: $light-2;
	padding: 20px;
	text-align: center;
	a {
		color: $light-2;
	}
}

.scroll-to-top-btn {
	display: inline-flex;
	position: absolute;
	right: 20px;
	cursor: pointer;
}

