js:
$(document).ready(function() {

$('.nav li a').on('click', function(e) {
    e.preventDefault();
    var scrollAnchor = $(this).parent('li').attr('aria-controls');
    var scrollPoint = $('div.nav-penal[id="' + scrollAnchor + '"]').offset().top - 55;

    $('html, body').animate({
        scrollTop: scrollPoint
    }, 1000);

    return false;
});

MenuNavigation();

$(window).scroll(function() {
    MenuNavigation();
});

$(window).resize(function() {
    MenuNavigation();
});

function MenuNavigation() {
    if ($(window).width() > 1024) {
        if ($('body').find('.nav').length > 0) {
            var menuPosition = $('.nav-wrap').offset().top;
            var windscroll = $(window).scrollTop();
            var containerWidth = $('.navigation-wrapper').outerWidth();
            if (windscroll >= menuPosition) {
                $('.navigation-wrapper .nav').addClass('fixed-nav').css('width', containerWidth);
                $('.navigation-wrapper .nav-penal').each(function(i) {
                    if ($(this).offset().top <= windscroll + 60) {
                        $('.nav li.active').removeClass('active');
                        $('.nav li').eq(i).addClass('active');
                    }
                });
            } else {
                $('.navigation-wrapper .nav').removeClass('fixed-nav').css('width', '100%');
                $('.nav li.active').removeClass('active');
                $('.nav li:first').addClass('active');
            }
        }
    }
}
});

