// init vars
var documentHeight = 0;
var offsetMain = 0; // main divs are always on top = 0 position

var viewportHeight;
var windowScroll;
var newMainHeight;

function init() {
  console.log('init');

  getViewportHeight();
  resizeMainDivs();
  positionScrollLine();
}

function getViewportHeight() {
  viewportHeight = $(window).innerHeight();
}

function resizeMainDivs() {
  $('.main').each(function() {
    // make each main div the height of the viewport
    $(this).height(viewportHeight);
    // get total height of all main divs together
    documentHeight = documentHeight + viewportHeight;
  });

  // make document as high as the content (for scrolling)
  $('html').height(documentHeight)
}

function positionScrollLine() {
  // scroll line on the bottom
  $('.scroll-line').css('top', viewportHeight);
}

function getNewMainHeight() {
  windowScroll = $(window).scrollTop();
  newMainHeight = viewportHeight - windowScroll;

  $('.main--top').height(newMainHeight);
}

// on scroll
$(window).on('scroll', function() {  
  getNewMainHeight();
})

//on window resize
$(window).resize(function() {
  getViewportHeight();
  resizeMainDivs();
  positionScrollLine();
  getNewMainHeight();
})

//init
init();

