var sidebar = $('.secondary');
var container = $('.main');

var sidebarStartingPosition = sidebar.offset();
var sidebarStartingWidth = sidebar.width();
var sidebarStartingHeight = sidebar.height();
var startingContainerBottom = container.offset().top + container.height();
var startingContainerHeight = container.height();

$(window).resize(function(){
    sidebarStartingPosition = sidebar.offset();
    sidebarStartingWidth = sidebar.width();
    sidebarStartingHeight = sidebar.height();
    startingContainerBottom = container.offset().top + container.height();
    startingContainerHeight = container.height();
});

// console.log(sidebarStartingWidth);

$(window).bind("scroll", function() {
    // console.log(sidebarStartingPosition);
    var scrollPosition = $(window).scrollTop();
    // console.log(scrollPosition);
    if (scrollPosition > sidebarStartingPosition.top) {
        if ((scrollPosition + sidebarStartingHeight) < startingContainerBottom) {
            console.log('fixed!');
            sidebar.addClass('fixed');
            sidebar.css({
                'left':sidebarStartingPosition.left,
                'width':sidebarStartingWidth,
                'top':0
            });
            sidebar.removeClass('fixedBottom');
        } else {
            console.log('bottom!');
            sidebar.removeClass('fixed');
            sidebar.addClass('fixedBottom');
            sidebar.css({
                // 'top':auto,
                // 'bottom':startingContainerBottom,
                'left':0,//sidebarStartingPosition.left,
                'width':sidebarStartingWidth,
                'top':startingContainerHeight - sidebarStartingHeight
            });
        }

    } else {
        console.log('top!');
        sidebar.removeClass('fixed');
        sidebar.removeClass('fixedBottom');
        sidebar.css({
            'left':0,
            'width':'100%',
            'top':0
        });
    }
});

