$(document).ready(function() {

  const $fixedElem = $('.js-fixed');

  $.each($fixedElem, function() {
    const $currentElem = $(this);
    const $placeholder = $currentElem.clone();

    $placeholder.addClass('placeholder');
    $currentElem.after($placeholder);
  });

});

