// Global variables
var header  = document.querySelector( 'header.branding' ),
    oldPos  = 0, 
    newPos, direction;

// Scroll direction detection
function detectDirection() {
  newPos = window.pageYOffset;
  ( newPos > oldPos ) ? direction = 'down' : direction = 'up';
  oldPos = newPos;
  return direction;
}

// Scroll function
window.onscroll = function() {

  // Scoped variables
  var scrollDir = detectDirection(),
      bottomOut = window.innerHeight + window.pageYOffset >= document.body.offsetHeight;

  // Where the magic happens
  ( window.pageYOffset > 300 && scrollDir == 'down' && !bottomOut ) ? header.classList.add( 'slide-up' ) : header.classList.remove( 'slide-up' );
};

