}

div {
  width: 200px;
  background: rgba(255,0,0,0.5);
  text-align: center;
  padding: 100px 0;
}

.fixed {
  position: fixed;
  top: 40px;
  left: 100px;
  z-index: 3;
}

.translate {
  transform: translate3d(0,0,0);
}

.relative {
  position: relative;
  margin: 50px auto;
  z-index: 1;
